comment.body:
I think this could be extracted to a method, something like

```rs
async fn cleanup_sweep_once(&self, attempt: usize) -> bool {
  let mut any_deferred = false;
  for session in self.account_manager.sessions_iter() {
    match session.key_packages().cleanup_relay_key_packages_once().await {
      Ok(AlreadyCompleted) => { /* debug log */ }
      Ok(DeferredRecentConsumedKeyPackage) => { any_deferred = true; /* info log */ }
      Ok(DeletedAndPublished { deleted }) => { /* info log */ }
      Err(error) => { /* warn log */ }
    }
  }
  any_deferred
}
```

And then this becomes:

```rs
  for attempt in 1..=KEY_PACKAGE_RELAY_CLEANUP_MAX_ATTEMPTS {
      if self.wait_through_grace_or_shutdown(&mut shutdown_rx).await.is_break() {
          return;
      }
      if !self.cleanup_sweep_once(attempt).await {
          return;
      }
  }
  tracing::warn!(/* remained deferred after all attempts */);
```

